namespace Puck.SdfVm;

/// <summary>
/// What the tier views (<see cref="DebugViewModes.Rates"/>, <see cref="DebugViewModes.RateFlash"/>) read about one rated
/// item: the tier it updates at in the value modulo four, plus <see cref="Updated"/> on a frame it updated. A body's code
/// rides the unused fourth component of each of its dynamic-transform slots' position rows, and a screen's the third
/// component of its ripple record's state row; both are written only while a tier view shows, and zero otherwise. The
/// kernels read each member as <c>SDF_RATE_*</c>, generated by <see cref="SdfIsaHlsl"/>.
/// </summary>
public enum SdfUpdateRateCode : byte {
    /// <summary>Nothing a lever rates: drawn untinted.</summary>
    None = 0,
    /// <summary>Rated, and updating every frame: drawn untinted.</summary>
    Every = 1,
    /// <summary>Held to the 30 Hz tier.</summary>
    Half = 2,
    /// <summary>Held to the 15 Hz tier.</summary>
    Quarter = 3,
    /// <summary>Added to a tier on a frame the item updated.</summary>
    Updated = 4,
}
